function trendPath(points){const known=points.map((point,index)=>({...point,index})).filter((point)=>point.value!==null&&point.value!==undefined);if(!known.length)return{path:"",dots:[],max:null};const max=Math.max(...known.map((point)=>point.value),1),width=360,height=112,pad=8,step=points.length>1?(width-pad*2)/(points.length-1):0;let open=false,path="";const dots=[];for(const [index,point] of points.entries()){if(point.value===null||point.value===undefined){open=false;continue;}const x=points.length>1?pad+index*step:width/2,y=height-pad-(point.value/max)*(height-pad*2);path+=`${open?" L":"M"} ${x.toFixed(1)} ${y.toFixed(1)}`;open=true;dots.push({x,y,value:point.value,label:point.label});}return{path,dots,max};}
