function trafficTrendChart(key,points){const chart=trendPath(points),latest=points.at(-1),first=points[0]?.label,last=points.at(-1)?.label;return `<article class="trend-card metric-${esc(key)}"><header><span>${t(key==="website_uv"&&portfolioMode==="daily"&&trendPeriod==="weekly"?"weekly_uv":key)}</span><strong>${fmt(latest?.value)}</strong><small>${esc(deltaLabel(points))}</small></header>${chart.path?`<svg viewBox="0 0 360 112" role="img" aria-label="${esc(t(key))}"><path class="trend-grid" d="M8 104 H352 M8 56 H352 M8 8 H352"/><path class="trend-line" d="${chart.path}"/>${chart.dots.map((dot)=>`<circle cx="${dot.x.toFixed(1)}" cy="${dot.y.toFixed(1)}" r="3"><title>${esc(dot.label)}: ${fmt(dot.value)}</title></circle>`).join("")}</svg>`:`<div class="trend-empty">—</div>`}<footer><span>${esc(first??"—")}</span><span>${esc(last??"—")}</span></footer></article>`;}
